begin;
insert into auth.users(id) values ('11111111-1111-4111-8111-111111111111'), ('22222222-2222-4222-8222-222222222222');
insert into profiles(uid,email) select id,id::text||'@test.invalid' from auth.users;
insert into diary_entries(id,user_id,date,content) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','2026-09-29','Ficticio');
select test.ok(public.normalize_person_details('{"relacion":{"entries":[{"value":"novia","date":"2025-06-02"},{"value":"Novia","date":"2025-06-02"},{"value":"Novia","date":"2025-07-02"}]}}') = '{"relacion":{"entries":[{"value":"novia","date":"2025-06-02"}]}}'::jsonb,'person repeated relationship collapses across dates and case');
select test.ok(jsonb_array_length(public.normalize_person_details('{"relacion":{"entries":[{"value":"novia","date":"2025-01-01"},{"value":"amiga","date":"2025-02-01"},{"value":"novia","date":"2025-03-01"}]}}')->'relacion'->'entries')=3,'real relationship transitions including return preserved');
select test.ok(jsonb_array_length(public.normalize_person_details('{"detalles":{"entries":[{"value":"Café.","date":"2025-01-01"},{"value":"café","date":"2025-01-01"},{"value":"Café","date":"2025-02-01"}]}}')->'detalles'->'entries')=2,'facts deduplicate only within same diary date');
select test.ok(public.normalize_person_details('{"rol":{"entries":[{"value":"desconocido","date":"2025-01-01"}]},"cumpleanos":"1 enero"}') = '{"cumpleaños":{"entries":[{"value":"1 enero","date":""}]}}'::jsonb,'unknown markers removed and legacy birthday key merged without inventing date');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into people(user_id,name,details) values('11111111-1111-4111-8111-111111111111','  Persona   prueba  ','{"relacion":{"entries":[{"value":"amigo","date":"2025-01-01"},{"value":"Amigo","date":"2025-02-01"}]}}');
select test.ok((select name='Persona prueba' and jsonb_array_length(details->'relacion'->'entries')=1 from people where name='Persona prueba'),'authenticated writes normalize safely through trigger');
insert into people(user_id,name) values ('11111111-1111-4111-8111-111111111111','PERSONA PRUEBA');
select test.ok((select count(*)=2 from people),'homonyms are separate rows even when names normalize equally');
delete from people where name='PERSONA PRUEBA';
update diary_entries set mentioned_people=array['Persona prueba','PERSONA PRUEBA'] where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select test.ok((select mention_count=1 from people where name='Persona prueba'),'multiple mentions in one diary date count once');
update people set mention_count=999 where name='Persona prueba';
select test.ok((select mention_count=1 from people where name='Persona prueba'),'reanalysis cannot inflate mention count');
insert into diary_entries(user_id,date,content,mentioned_people) values('11111111-1111-4111-8111-111111111111','2026-09-28','Ficticio',array['Persona prueba']);
select test.ok((select mention_count=2 from people where name='Persona prueba'),'another diary date adds one mention');
update diary_entries set mentioned_people='{}' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select test.ok((select mention_count=1 from people where name='Persona prueba'),'removing a mention updates count');
delete from diary_entries where user_id='11111111-1111-4111-8111-111111111111' and date='2026-09-28';
select test.ok((select mention_count=0 from people where name='Persona prueba'),'deleting diary entry updates count');
select test.ok((select count(*)=0 from people where user_id='22222222-2222-4222-8222-222222222222'),'person integrity preserves owner isolation');
select test.raises('select public.enforce_person_information()','42501','person trigger cannot be called directly by browser');
select test.raises('select public.refresh_diary_person_mentions()','42501','mention trigger cannot be called directly by browser');
select test.raises('select * from public.person_information_repair_backups','42501','private repair backup is not browser readable');
select test.raises('truncate public.person_information_repair_backups','42501','repair backup cannot be truncated by browser');
select test.raises('select public.rename_diary_person_mentions()','42501','rename trigger is not a public RPC');
insert into diary_entries(user_id,date,content,mentioned_people) values('11111111-1111-4111-8111-111111111111','2026-09-27','Ficticio',array['Persona prueba']);
update people set name='Nombre nuevo' where name='Persona prueba';
select test.ok((select mention_count=1 from people where name='Nombre nuevo'),'renaming a person preserves historical mention counts');
select test.ok((select mentioned_people=array['Nombre nuevo'] from diary_entries where date='2026-09-27' and user_id='11111111-1111-4111-8111-111111111111'),'renaming updates owner diary references atomically');
reset role;
select count(*) as passed_people_checks from test.results;
rollback;
